scan_linter_check.script:
(function(engine) {
    if (!engine.rootNode) {
        return;
    }
    var ast = new global.EcsAst(engine.rootNode);
    var hits = new global.EcsCodeQuality(ast).swallowedErrors();
    var report = new global.EcsReport(engine, {
        ruleId: 'JS-004',
        title: 'Empty or swallowing catch block',
        recommendation: 'Handle the error: log it with context (gs.error with the exception and what was being done), rethrow, or return a clear failure. If ignoring it is really intended, say why in a comment and mute this finding.'
    });
    for (var i = 0; i < hits.length; i++) {
        report.add(hits[i].node, hits[i].message);
    }
    report.flush();
})(engine);
